class Solution {
public:
    vector<int> closestNode(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        vector<vector<int>> g(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<int> answer;
        for (auto& item : query) {
            int a = item[0], b = item[1], node = item[2];
            vector<int> parent(n, -1);
            queue<int> q; q.push(a); parent[a] = a;
            while (!q.empty() && parent[b] == -1) {
                int u = q.front(); q.pop();
                for (int v : g[u]) if (parent[v] == -1) { parent[v] = u; q.push(v); }
            }
            vector<int> dist(n, -1), owner(n, -1);
            queue<int> bfs;
            for (int u = b;; u = parent[u]) {
                dist[u] = 0; owner[u] = u; bfs.push(u);
                if (u == a) break;
            }
            while (!bfs.empty() && dist[node] == -1) {
                int u = bfs.front(); bfs.pop();
                for (int v : g[u]) if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    owner[v] = owner[u]; bfs.push(v);
                }
            }
            answer.push_back(owner[node]);
        }
        return answer;
    }
};
